package microgrid

import "testing"

func benchActual(b *testing.B, futurePlans, executedHistory int) {
	b.Helper()
	p := baseParams()
	p.ReserveSlots = 0
	c, err := New(p, 90)
	if err != nil {
		b.Fatal(err)
	}
	loads := make([]int, executedHistory+futurePlans+4)
	if _, err := c.UpdateLoads(0, loads); err != nil {
		b.Fatal(err)
	}
	// A long executed history is generated by closing slots, each with an
	// idle actual; accepted history is discarded as slots advance.
	for t := 0; t < executedHistory; t++ {
		if _, err := c.RegisterActual(t, Idle, 0); err != nil {
			b.Fatalf("history slot %d: %v", t, err)
		}
	}
	cur := c.CurrentSlot()
	plans := make([]SlotPlan, futurePlans)
	for i := range plans {
		plans[i] = SlotPlan{Idle, 0}
	}
	if _, err := c.SubmitPlan(cur+1, plans); err != nil {
		b.Fatalf("submit future: %v", err)
	}
	b.ResetTimer()
	if b.N > futurePlans {
		b.N = futurePlans
	}
	for i := 0; i < b.N; i++ {
		// Closing the current idle slot costs one revalidation pass over
		// exactly futurePlans accepted slots.
		if _, err := c.RegisterActual(cur, Idle, 0); err != nil {
			b.Fatal(err)
		}
		// Re-arm: undo time by recreating is expensive, so instead keep
		// closing; plans shrink naturally, which still bounds the walk by
		// remaining accepted slots.
		cur++
	}
}

func BenchmarkActualSmallFuture(b *testing.B) { benchActual(b, 16, 1000) }
func BenchmarkActualLargeFuture(b *testing.B) { benchActual(b, 1024, 1000) }
